  creek: { x0: -90, step: 10, dz: [0, -5.4, -6.2, -4.9, -1.8, -1.8, -0.5, 1.2, 0.5, -0.2, 0, -0.5, -1.6, 0, -0.1, 0, 0, -0.5, 0], w: [1, 2.5, 2.5, 2.5, 2.5, 2.27, 1.46, 1.77, 2.37, 1.61, 1, 1.21, 1.33, 1, 1.1, 1, 1, 1.21, 1] },
